{
  "site": "books",
  "description": "Books to Scrape (scraping sandbox): browse the catalogue, filter by category, open a book. Hand-written from recording.jsonl.",
  "origin": "https://books.toscrape.com",
  "loggedIn": false,
  "usage": "clify books <command> [--param value ...] [--fields a,b] [--limit N] [--yes]",
  "tips": [
    "Results can be long objects: pass --fields with the keys you need (dot paths work, e.g. --fields title,content_urls.desktop.page).",
    "List results include count; if a command has a --page param, more results are on the next page.",
    "Commands marked writes:true return a dry-run preview until you add --yes."
  ],
  "commands": [
    {
      "name": "list-books",
      "summary": "All books, 20 per page",
      "params": [
        {
          "name": "--page",
          "type": "number",
          "default": 1
        }
      ],
      "example": "clify books list-books --page \"2\""
    },
    {
      "name": "list-category",
      "summary": "Books in one category (slug like mystery_3, travel_2)",
      "params": [
        {
          "name": "--category",
          "type": "string",
          "required": true,
          "description": "category slug, e.g. mystery_3"
        }
      ],
      "example": "clify books list-category --category \"mystery_3\""
    },
    {
      "name": "get-book",
      "summary": "One book's detail page",
      "params": [
        {
          "name": "--slug",
          "type": "string",
          "required": true,
          "description": "e.g. the-mysterious-affair-at-styles-hercule-poirot-1_452"
        }
      ],
      "example": "clify books get-book --slug \"the-mysterious-affair-at-styles-hercule-poirot-1_452\""
    }
  ]
}

